import{_ as l,o as t,c as i,a4 as a}from"./chunks/framework.DzJZdBQK.js";const h=JSON.parse('{"title":"写作课作业-118","description":"","frontmatter":{"date":"2021-04-10T14:23:00","title":"写作课作业-118","categories":["写作","作业","一年顶十年"],"tags":["写作","作业","一年顶十年"]},"headers":[{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/118.md","filePath":"posts/homework/118.md"}'),o={name:"posts/homework/118.md"};function r(p,e,s,n,_,c){return t(),i("div",null,[...e[0]||(e[0]=[a('<blockquote><p>《一年顶十年》之《牛人 如何通过持续见牛人突破自己？》</p></blockquote><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><ul><li>通过见牛人见识到很多可能性，思维更加开阔，成长动力更足。</li><li>五个渠道找牛人：新媒体平台； 社群、培训班、付费约见平台；他人引荐；自身吸引。</li><li>跟多位 同一领域的牛人交流，可以了解更多“门道”，少走很多弯路；同时可以搭建这一领域的专家网络。</li><li>见牛人的准备：提前了解；梳理自己；好好休息；收拾自己；带上礼物。</li><li>见牛人不聊的事情：不要问对方的隐私；不要说其他人的坏话；切莫交浅言深。</li><li>见牛人后需要做的事情：反馈；推荐；分享；问候。</li><li>见牛人时不要着急，慢慢来会更好。</li><li>约见牛人时不要给差评。</li><li>做一个超级连接者，会让你更有价值。</li></ul><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>网络为我们提供了更多可以观察和学习牛人的方式，要好好利用，其中的一个点就是互动。</p><p>自己成为牛人，成为有作品的人。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',13)])])}const u=l(o,[["render",r]]);export{h as __pageData,u as default};
